/// <summary>
/// Triggering the SO confirmation framework to run the credit check flow.
/// </summary>
/// <param name = "_salesTable">SalesTable reference</param>
public static void SOProformaPosting(SalesTable _salesTable)
{

    SalesFormLetter salesFormLetter;
    salesFormLetter = SalesFormLetter::construct(DocumentStatus::Confirmation);

    salesFormLetter.update(_salesTable, systemDateGet(), SalesUpdate::All, AccountOrder::None, NoYes::Yes, NoYes::No, NoYes::No);

    infolog.cut();
}

public static void deletePreviousCreditHoldList(SalesTable _salesTable)
{
    CredManTable    credManTableDel;
    CredManTrans    credManTrans;
    SalesLine       salesLine;

    ttsbegin;
    _salesTable.selectForUpdate(true);
    _salesTable.CredManId = '';
    _salesTable.update();
    ttscommit;

    ttsbegin;
    select forupdate credManTableDel
        where credManTableDel.SalesId == _salesTable.SalesId;

    credManTableDel.delete();
    ttscommit;

    ttsbegin;
    while select forupdate credManTrans
        join salesLine
        where credManTrans.InventTransId == salesLine.InventTransId
        && salesLine.SalesId == _salesTable.SalesId
    {
        credManTrans.delete();
    }
    ttscommit;

}
